def check(actual, expected):
    if actual != expected:
        raise AssertionError(repr(actual) + ' != ' + repr(expected))
# With a precision, zeros fill between the sign or the 0x/0o prefix and the digits; '#' adds no prefix to a decimal.
check('%010.3d|%+05.3x|%#5.3d|%#10.0d|%+010.3d' % (-42, 65, 0.000123, 42, -42), '-000000042|+0041|  000|        42|-000000042')
check('%05.2d|%-05.2d|% 05.2i|%+.3u|%.0d|%.0x|%#.0o' % (7, 7, 7, 7, 0, 0, 0), '00007|07   | 0007|+007|0|0|0o0')
check('%#x|%#X|%#o|%#d|%#08x|%#-8X|%#8.4o' % (255, 255, 8, 5, 255, 255, 8), '0xff|0XFF|0o10|5|0x0000ff|0XFF    |  0o0010')
check('%*.*d|%-*.*x|%0*d' % (8, 3, -5, 8, 3, 255, 6, -5), '    -005|0ff     |-00005')
